--- a/cc/silo/transaction.cc
+++ b/cc/silo/transaction.cc
@@ -40,15 +40,49 @@
 #endif
 // EVOLVE-BLOCK-BEGIN silo-function-policy
 #if SILO_POLICY_VARIANT
-struct PolicyState { };
-uint32_t policy_after_abort(PolicyState&, const izanagi_silo_api::AbortContext&) noexcept {
-  return 0u;
-}
+constexpr uint32_t kStreakCap = 4u;
+
+struct PolicyState {
+  uint32_t streak = 0u;
+};
+
+uint32_t window_mask(uint32_t level) noexcept {
+  if (level <= 1u) {
+    return 0u;
+  }
+  if (level == 2u) {
+    return 1u;
+  }
+  if (level == 3u) {
+    return 3u;
+  }
+  if (level == 4u) {
+    return 7u;
+  }
+  return 15u;
+}
+
+uint32_t policy_after_abort(PolicyState& state, const izanagi_silo_api::AbortContext& ctx) noexcept {
+  uint32_t next = std::min(state.streak + 1u, kStreakCap);
+  state.streak = next;
+  uint32_t level = next;
+  if (ctx.reason == izanagi_silo_api::AbortReason::lock_conflict) {
+    level = std::min(next + 1u, kStreakCap);
+  }
+  uint32_t mask = window_mask(level);
+  uint32_t r = static_cast<uint32_t>(ctx.rand);
+  return r & mask;
+}
+
 izanagi_silo_api::LockResponse policy_on_lock_conflict(PolicyState&, const izanagi_silo_api::LockContext&) noexcept {
-  return izanagi_silo_api::LockResponse{izanagi_silo_api::PolicyAction::abort, 0u};
-}
-void policy_on_commit(PolicyState&, const izanagi_silo_api::CommitContext&) noexcept {
-}
+  izanagi_silo_api::LockResponse stop = izanagi_silo_api::LockResponse{izanagi_silo_api::PolicyAction::abort, 0u};
+  return stop;
+}
+
+void policy_on_commit(PolicyState& state, const izanagi_silo_api::CommitContext&) noexcept {
+  state.streak = 0u;
+}
+
 #else
 #endif
 // EVOLVE-BLOCK-END silo-function-policy
